import{_ as e,o as a,c as d,ag as o}from"./chunks/framework.DaCm-iTo.js";const h=JSON.parse('{"title":"EmakiStorage","description":"","frontmatter":{},"headers":[],"relativePath":"modules/storage/index.md","filePath":"modules/storage/index.md","lastUpdated":null}'),s={name:"modules/storage/index.md"};function c(r,t,i,n,l,p){return a(),d("div",null,[...t[0]||(t[0]=[o(`<h1 id="emakistorage" tabindex="-1">EmakiStorage <a class="header-anchor" href="#emakistorage" aria-label="Permalink to &quot;EmakiStorage&quot;">​</a></h1><p>EmakiStorage 是 Emaki 系列的 GUI 仓库模块。它把玩家物品存进按逻辑槽位组织的仓库中，单个槽位可以存放 <code>long</code> 量级的数量，同时完整保留原始 <code>ItemStack</code>（组件、附魔、PDC 全部原样保存）。</p><p>仓库界面由 <code>gui/storage_gui.yml</code> 模板描述，容量由 <code>config.yml</code> 与权限档位、命令授予、付费购买共同决定，存取行为通过 CoreLib Action、公开 API 与 Bukkit 事件对外开放。</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>模块版本</td><td><code>1.0.6</code></td></tr><tr><td>API Jar</td><td><code>emaki-storage-api-1.0.6.jar</code></td></tr><tr><td>主类</td><td><code>emaki.jiuwu.craft.storage.EmakiStoragePlugin</code></td></tr><tr><td>主命令</td><td><code>/emakistorage</code></td></tr><tr><td>别名</td><td><code>/estorage</code></td></tr><tr><td>硬依赖</td><td>EmakiCoreLib</td></tr><tr><td>软依赖</td><td>PlaceholderAPI</td></tr><tr><td>描述符基线</td><td><code>api-version: &quot;1.21.8&quot;</code>、<code>folia-supported: true</code></td></tr><tr><td>Java</td><td>Java 25</td></tr><tr><td>主要权限</td><td><code>emakistorage.use</code>（默认 true）、<code>emakistorage.unlock.purchase</code>（默认 true）、<code>emakistorage.reload</code>（op）、<code>emakistorage.debug</code>（op）、<code>emakistorage.admin</code>（op）</td></tr></tbody></table><h2 id="功能页面" tabindex="-1">功能页面 <a class="header-anchor" href="#功能页面" aria-label="Permalink to &quot;功能页面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>内容</th></tr></thead><tbody><tr><td><a href="./commands.html">命令与权限</a></td><td><code>/emakistorage</code>、<code>/estorage</code> 的子命令、权限节点与示例。</td></tr><tr><td><a href="./configuration.html">配置详解</a></td><td><code>config.yml</code> 的 <code>unlock</code>、<code>behavior</code>、<code>search</code>、<code>persistence</code>、<code>logging</code> 等键。</td></tr><tr><td><a href="./capacity.html">容量与缩容</a></td><td><code>capacity</code> 段、四来源容量、三级 <code>stackLimit</code> 与缩容溢出策略。</td></tr><tr><td><a href="./gui.html">界面与展示</a></td><td><code>gui</code> 与 <code>display</code> 段、<code>gui/storage_gui.yml</code> 模板结构与点击语义。</td></tr><tr><td><a href="./unlock-costs.html">付费扩容档位</a></td><td><code>unlock_costs.yml</code> 的档位、逐格计价与支付顺序。</td></tr><tr><td><a href="./corelib-actions.html">CoreLib 动作</a></td><td>EmakiStorage 注册到 CoreLib ActionRegistry 的 5 个动作。</td></tr><tr><td><a href="./api.html">API 与集成</a></td><td>第三方插件通过 <code>emaki-storage-api</code> 调用仓库的方式与结果模型。</td></tr><tr><td><a href="./events.html">事件 API</a></td><td><code>StorageDepositEvent</code>、<code>StorageWithdrawEvent</code>、<code>StorageUnlockEvent</code> 三个 Bukkit 事件。</td></tr><tr><td><a href="./placeholders.html">PlaceholderAPI 占位符</a></td><td><code>emakistorage</code> 扩展的 10 个占位符与求值线程约束。</td></tr></tbody></table><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to &quot;核心能力&quot;">​</a></h2><ul><li><strong>单槽 <code>long</code> 量级存储</strong>：一个逻辑槽位存放一种物品，数量上限来自三级 <code>stackLimit</code> 配置，而不是原版 64/99 堆叠。</li><li><strong>完整保留原始物品</strong>：去重口径是全量 <code>ItemStack#equals</code>（组件、附魔、自定义 PDC 全部参与比较），不引入任何哈希签名层，因此两个组件不同的同材质物品不会被合并成一个条目。</li><li><strong>槽位是唯一容量真实来源</strong>：<code>effectiveSlots</code> 由 <code>base_slots</code> + 权限档位 + 命令授予 + 付费购买四个来源相加后钳制得出，页数由槽位数推导（<code>ceil(effectiveSlots / 每页格数)</code>），不存在「先定页数再算槽位」的反向推导。</li><li><strong>混用存入</strong>：展示区任意槽位（光标带物品时点击）与固定投入口 <code>deposit_slot</code> 两条路径共用同一套事务实现，容量检查、过滤器、事件发布与流水记录只存在一份。</li><li><strong>1–99 占用率渲染</strong>：<code>display.amount_mode: percent</code> 时用物品 <code>amount</code> 字段的 1–99 表达占用百分比，精确数量写进 lore。<code>max_stack_size</code> 组件的合法范围就是 1–99，因此不涉及任何发包技巧。</li><li><strong>搜索与排序</strong>：搜索为子串匹配，永不编译正则；排序是显式「整理」动作，会重写条目顺序。</li><li><strong>零丢失缩容</strong>：容量调小导致占用超出时有四种策略，全部不会造成不可逆数据丢失，不提供 <code>drop</code> / <code>delete</code>。</li><li><strong>流水日志只写不读</strong>：业务逻辑永不读取日志文件，<code>ADMIN_SET</code> / <code>ADMIN_GIVE</code> / <code>ADMIN_CLEAR</code> 三类管理员操作强制记录。</li></ul><h2 id="存档设计" tabindex="-1">存档设计 <a class="header-anchor" href="#存档设计" aria-label="Permalink to &quot;存档设计&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>实现</th></tr></thead><tbody><tr><td>条目数据</td><td>二进制单文件 <code>storage.dat</code>，文件魔数 <code>EMSTOR</code>，格式版本 <code>1</code>。</td></tr><tr><td>写入策略</td><td><strong>全量重写</strong>，不是追加写。每次保存都产出一个已经紧凑的文件，因此没有压实器、没有垃圾率统计、没有悬空 id 修复。</td></tr><tr><td>写入顺序</td><td>先写同目录 <code>.tmp</code>，再读回校验记录数，最后原子替换。写入失败时保留旧文件并删除 tmp。</td></tr><tr><td>逐条目分帧</td><td>每条记录单独分帧，使用 Paper 的 <code>ItemStack#serializeAsBytes()</code> / <code>deserializeBytes(byte[])</code>，携带 <code>DataVersion</code> 并在读取时过 DataFixer。</td></tr><tr><td>损坏隔离</td><td>解码失败的记录被写入 <code>corrupt/&lt;uuid&gt;-&lt;时间戳&gt;.dat</code>，其余记录正常载入。</td></tr><tr><td>可手改数据</td><td>槽位数、<code>stackLimit</code>、排序模式等存在 <code>meta.yml</code>（文本 YAML），条目载荷保持二进制，因为 YAML 无法表达完整 <code>ItemStack</code>。</td></tr></tbody></table><h2 id="文件结构" tabindex="-1">文件结构 <a class="header-anchor" href="#文件结构" aria-label="Permalink to &quot;文件结构&quot;">​</a></h2><p>服务器运行后，EmakiStorage 主要使用以下文件：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/EmakiStorage/</span></span>
<span class="line"><span>├─ config.yml</span></span>
<span class="line"><span>├─ unlock_costs.yml</span></span>
<span class="line"><span>├─ gui/</span></span>
<span class="line"><span>│  └─ storage_gui.yml</span></span>
<span class="line"><span>├─ lang/</span></span>
<span class="line"><span>│  ├─ zh_CN.yml</span></span>
<span class="line"><span>│  └─ en_US.yml</span></span>
<span class="line"><span>├─ data/</span></span>
<span class="line"><span>│  └─ &lt;uuid&gt;/</span></span>
<span class="line"><span>│     ├─ storage.dat</span></span>
<span class="line"><span>│     └─ meta.yml</span></span>
<span class="line"><span>├─ logs/</span></span>
<span class="line"><span>│  └─ &lt;uuid&gt;/</span></span>
<span class="line"><span>│     └─ &lt;yyyy-MM-dd&gt;.log</span></span>
<span class="line"><span>├─ corrupt/</span></span>
<span class="line"><span>└─ exports/</span></span></code></pre></div><table tabindex="0"><thead><tr><th>路径</th><th>说明</th></tr></thead><tbody><tr><td><code>config.yml</code></td><td>主配置：界面、容量、扩容缩容、展示、存取行为、搜索、持久化、日志。</td></tr><tr><td><code>unlock_costs.yml</code></td><td>付费扩容档位。业务数据文件，只在缺失时释放一次，版本升级不覆盖管理员内容。</td></tr><tr><td><code>gui/storage_gui.yml</code></td><td>仓库界面模板。功能区只配 <code>offset</code>，槽位号由 <code>gui.storage_rows</code> 换算。</td></tr><tr><td><code>lang/*.yml</code></td><td>界面、命令、扩容与控制台提示文案。</td></tr><tr><td><code>data/&lt;uuid&gt;/storage.dat</code></td><td>该玩家的条目数据，二进制全量重写。</td></tr><tr><td><code>data/&lt;uuid&gt;/meta.yml</code></td><td>该玩家的槽位数、<code>stackLimit</code>、排序模式等可手改元数据。</td></tr><tr><td><code>logs/&lt;uuid&gt;/&lt;yyyy-MM-dd&gt;.log</code></td><td>存取流水，按玩家目录 + 按日切文件，只写不读。</td></tr><tr><td><code>corrupt/</code></td><td>解码失败记录的隔离目录。</td></tr><tr><td><code>exports/</code></td><td><code>/estorage export</code> 生成的可读 YAML 转储。</td></tr></tbody></table><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><ol><li>把 <code>EmakiCoreLib-*.jar</code> 与 <code>EmakiStorage-*.jar</code> 放入服务器 <code>plugins/</code>。</li><li>不要把 <code>emaki-storage-api-*.jar</code> 放进服务器 <code>plugins/</code>；API Jar 只给开发者作为编译依赖使用。</li><li>首次启动后检查 <code>plugins/EmakiStorage/config.yml</code> 与 <code>unlock_costs.yml</code>。</li><li>打开自己的仓库：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/estorage</span></span></code></pre></div><ol start="5"><li>修改配置后重载配置、语言与 GUI 模板：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/estorage reload</span></span></code></pre></div><ol start="6"><li>给在线玩家追加槽位并查看容量拆解：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/estorage slot grant Steve 10</span></span>
<span class="line"><span>/estorage info Steve</span></span></code></pre></div><h2 id="使用提示" tabindex="-1">使用提示 <a class="header-anchor" href="#使用提示" aria-label="Permalink to &quot;使用提示&quot;">​</a></h2><ul><li><code>gui.deposit_feedback</code> 不建议设为 <code>none</code>。混用存入下物品会按条目顺序落位，可能出现在别的页，没有反馈时玩家会以为物品消失。</li><li><code>emakistorage.slots.&lt;n&gt;</code> 与 <code>emakistorage.stacklimit.&lt;n&gt;</code> 取所有生效档位中的最大值，且<strong>不支持通配</strong>。</li><li>调小 <code>capacity.base_slots</code> 不会吃掉玩家已授予或已购买的槽位，这三个来源分别持久化。</li><li>缩容溢出状态不持久化，它由容量与占用推导，在登录、重载、权限变化、命令授予时重新计算。</li><li>写类管理命令要求目标玩家在线，见 <a href="./commands.html">命令与权限</a>。</li></ul>`,24)])])}const m=e(s,[["render",c]]);export{h as __pageData,m as default};
